import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-subhead';
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const geometry = new THREE.PlaneGeometry(2.4, 1.5);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const grainAmount = uniform(0.03);
  const uvNode = uv();
  const texColor = texture(map, uvNode);

  const grain = uvNode.x.mul(37.13).sin().mul(uvNode.y.mul(91.7).sin()).mul(0.5).add(0.5);
  const grained = texColor.rgb.add(grain.sub(0.5).mul(grainAmount));

  material.colorNode = vec4(grained, texColor.a);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'home-subhead-plane';
  group.add(plane);

  const textMeshes = [];
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];

  textContent.forEach((item, index) => {
    const text = typeof item === 'string' ? item : item.text;
    const role = (item && item.role) || 'headline';
    const weight = (item && item.weight) || 400;

    let sizeEm = 0.34;
    if (role === 'hero') sizeEm = 0.62;
    else if (role === 'headline') sizeEm = 0.34;
    else if (role === 'subhead') sizeEm = 0.2;
    else if (role === 'body') sizeEm = 0.13;
    else if (role === 'caption') sizeEm = 0.09;

    const mesh = ctx.fontAtlas.createTextMesh({
      text,
      font: 'Lora',
      weight,
      size: sizeEm,
      color: '#e8ecf2',
      maxWidth: 2.2,
      align: 'center',
    });
    mesh.name = `home-subhead-text-${index}`;
    mesh.position.set(0, 0, 0.01);
    group.add(mesh);
    textMeshes.push(mesh);
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    textMeshes.forEach((mesh) => {
      mesh.geometry?.dispose?.();
      mesh.material?.dispose?.();
    });
  };

  return group;
}
